import type { NextAuthConfig, User as NextAuthUser } from 'next-auth'
import type { JWT } from 'next-auth/jwt'
import Credentials from 'next-auth/providers/credentials'
import { z } from 'zod'

declare module 'next-auth' {
  interface User {
    id?: string | undefined;
    name?: string | null | undefined;
    email?: string | null | undefined;
    image?: string | null | undefined;
    role: 'manager' | 'prep';
    restaurant_id: number;
  }
  
  interface Session {
    user: User
  }
}

declare module 'next-auth/jwt' {
  interface JWT {
    role: 'manager' | 'prep';
    restaurant_id: number;
  }
}

export const authConfig = {
  pages: {
    signIn: '/login',
  },
  callbacks: {
    authorized({ auth, request: { nextUrl } }) {
      const isLoggedIn = !!auth?.user
      const isManagerPath = nextUrl.pathname.startsWith('/manager-dash')
      const isPrepPath = nextUrl.pathname.startsWith('/prep-dash')

      if (isManagerPath) {
        return isLoggedIn && (auth?.user as { role: string })?.role === 'manager'
      } else if (isPrepPath) {
        return isLoggedIn
      }

      return true
    },
    jwt({ token, user }) {
      if (user) {
        token.role = user.role
        token.restaurant_id = user.restaurant_id
      }
      return token
    },
    session({ session, token }) {
      if (token) {
        session.user.role = token.role
        session.user.restaurant_id = token.restaurant_id
      }
      return session
    }
  },
  providers: [
    Credentials({
      async authorize(credentials) {
        const parsedCredentials = z
          .object({
            username: z.string().min(1),
            password: z.string().min(1),
            restaurant_id: z.string(),
            role: z.enum(['manager', 'prep'])
          })
          .safeParse(credentials)

        if (!parsedCredentials.success) return null

        // Here you would typically verify against your database
        // For now, using mock data
        const mockUser = {
          id: '1',
          name: parsedCredentials.data.username,
          role: parsedCredentials.data.role,
          restaurant_id: parseInt(parsedCredentials.data.restaurant_id)
        }

        return mockUser
      }
    })
  ]
} satisfies NextAuthConfig 